    "prompt": "아래 [업무 시나리오]를 참고하여 [업무 기능분해도]의 ⓐ~ⓒ를 각각 작성하시오.\n\n[보기 1]\n[업무 시나리오]\n\n[대출]\n\n- 회원은 무인 대출기에 회원증을 태그한다.\n\n- 대출기는 회원 자격(연체 및 대출정지 여부)을 확인하여, 대출이 불가한 회원이면 안내 메시지를 표시하고 종료한다.\n\n- 회원이 대출할 도서를 대출기에 올려놓으면 대출기는 RFID 태그로 도서를 인식한다.\n\n- 대출기는 인식한 도서의 예약 여부를 확인하여, 다른 회원이 예약한 도서이면 대출 불가로 안내하고, 예약이 없으면 대출 처리 후 반납 예정일을 표시한다.\n\n- 대출 처리가 끝나면 회원은 영수증 출력 여부를 선택한다.\n\n[반납]\n\n- 회원이 반납함에 도서를 투입하면 반납기는 도서를 인식한다.\n\n- 반납기는 반납 예정일과 반납일을 비교해 연체일수를 계산하고, 연체된 경우 연체일수만큼 대출정지를 부과한다.\n\n[보기 2]\n[업무 기능분해도]\n\n업무 | 단위 프로세스명 | 역할자\n\n대출 | 회원증 태그 | 회원\n\n대출 | ⓐ | 대출기\n\n대출 | 도서 올려놓기 | 회원\n\n대출 | 도서 인식 | 대출기\n\n대출 | ⓑ | 대출기\n\n대출 | 대출 처리 | 대출기\n\n대출 | 영수증 출력 여부 선택 | 회원\n\n반납 | 도서 투입 | 회원\n\n반납 | 도서 인식 | 반납기\n\n반납 | ⓒ | 반납기\n\n반납 | 대출정지 부과 | 반납기\n\n[작성 항목]\nⓐ 빈칸 작성\nⓑ 빈칸 작성\nⓒ 빈칸 작성",
