    "prompt": "C사는 대학 수강신청 시스템의 현행 업무를 자료 흐름도(DFD)로 분석하고 있다. [DFD 구성요소 정리]의 ⓐ~ⓒ에 들어갈 구성요소 명칭을 각각 작성하시오.\n\n[보기]\n[DFD 구성요소 정리]\n\n구성요소 | 표기 | 설명 | 수강신청 시스템의 예\n\nⓐ | 원(버블) | 입력된 데이터를 변환하여 출력 데이터를 만들어 내는 처리 활동 | 수강신청 검증, 수강 확정\n\n데이터 흐름 | 화살표 | 구성요소 사이에서 이동하는 데이터 | 신청과목 정보, 신청 결과\n\nⓑ | 평행선(이중선) | 처리 과정에서 필요한 데이터를 보관하고, 나중에 다시 읽어 쓰는 곳 | 강좌정보, 수강신청내역\n\nⓒ | 사각형 | 시스템 경계 밖에서 시스템에 데이터를 주거나 시스템으로부터 데이터를 받는 사람·조직·외부 시스템 | 학생, 학사관리시스템\n\n[작성 항목]\nⓐ 빈칸 작성\nⓑ 빈칸 작성\nⓒ 빈칸 작성",
