    "prompt": "C사 포인트 서비스는 메시지 브로커로부터 \"결제완료\" 메시지를 받아 포인트를 적립한다. 브로커는 최소 한 번(At-least-once) 전달을 보장한다. [장애 상황]을 해결하기 위한 조치로 가장 적절한 것을 고르시오.\n\n[보기 1]\n[장애 상황]\n\n포인트 서비스는 메시지를 받으면 ① 포인트 적립 DB 커밋 → ② 브로커에 처리 완료(ack) 응답 순으로 처리한다. 배포 중 인스턴스가 ①과 ② 사이에서 재시작되자, 브로커는 ack를 받지 못한 메시지를 다시 전달하였고 동일 결제 건에 포인트가 두 번 적립되었다.\n\n[보기 2]\n[포인트 적립 로그]\n\n10:02:11 messageId=MSG-88017 payNo=P-5521 point=+500 COMMIT\n10:02:11 instance restart (SIGTERM)\n10:02:19 messageId=MSG-88017 payNo=P-5521 point=+500 COMMIT ack=OK",
