    "prompt": "C사 쇼핑몰은 MSA로 전환하면서 서비스별로 팀을 나누었다. 아래 [장애 사례]를 MSA 원칙에 맞게 개선하는 방안으로 가장 적절한 것을 고르시오.\n\n[보기 1]\n[장애 사례]\n\n주문 서비스는 회원 등급별 할인을 계산하기 위해 회원 서비스가 관리하는 데이터베이스의 MEMBER 테이블을 직접 조인해 조회하고 있었다. 회원 서비스 팀이 자체 일정에 따라 MEMBER 테이블의 GRADE 컬럼명을 MBR_GRADE_CD로 변경해 배포하자, 주문 서비스의 주문 생성 기능이 전부 실패하였다.\n\n[보기 2]\n[주문 서비스의 조회 SQL]\n\nSELECT o.ORDER_NO, o.ORDER_AMT, m.GRADE\nFROM ORDER_DB.ORDERS o\nJOIN MEMBER_DB.MEMBER m ON m.MEMBER_ID = o.MEMBER_ID\nWHERE o.ORDER_NO = :orderNo;",
