      "주문 서비스에 회원 DB 읽기 전용 계정을 발급하여 실수로 회원 데이터를 수정하지 못하게 한다.",
      "회원 서비스와 주문 서비스를 하나의 서비스로 합쳐 같은 배포 단위로 관리한다.",
