    "prompt": "C사 인사 시스템의 논리 모델에서 \"사원\" 슈퍼타입이 \"정규직사원\"과 \"계약직사원\" 서브타입으로 나뉜다. [조건]을 가장 잘 만족하는 물리 모델 변환 방법을 고르시오.\n\n[보기 1]\n[논리 데이터 모델]\n[엔터티 사원]\nPK: 사원번호\n속성: 사원명, 입사일자, 부서코드 (FK), 고용구분코드\n[엔터티 정규직사원 / 종속]\nPK: 사원번호 (FK)\n속성: 호봉, 직급코드, 승진예정일자, …(고유 속성 12개)\n[엔터티 계약직사원 / 종속]\nPK: 사원번호 (FK)\n속성: 계약시작일자, 계약종료일자, 계약금액, …(고유 속성 10개)\n\n배타적 서브타입\n\n[보기 2]\n[조건]\n\n- 부서별 인원 현황처럼 고용 구분 없이 공통 속성만으로 전체 사원을 조회하는 업무가 매우 많다.\n\n- 호봉 산정(정규직)과 계약 갱신(계약직)은 각각 독립적으로 자주 처리되며, 서브타입별 고유 속성이 10개 이상으로 많다.\n\n- 서브타입 고유 속성 대부분은 해당 서브타입에서 반드시 값이 있어야 하므로 NOT NULL 제약으로 관리해야 한다.",
