    "title": "NULL을 0으로 바꾸는 식",
    "type": "복수선택형",
    "prompt": "급여 명세 화면에서 [보기]의 bonus가 NULL인 사원(강하준, 임도현, 문태오)은 0으로, 나머지는 원래 값으로 표시하려 한다. SELECT 절에 사용할 식으로 옳은 것을 모두 고르시오. (3개)\n\n[보기]\n[직원] EMP\n\nemp_id | emp_nm | dept_id | mgr_id | sal | bonus\n\nE1 | 강하준 | 10 | NULL | 6000 | NULL\n\nE2 | 윤서아 | 10 | E1 | 4500 | 500\n\nE3 | 임도현 | 20 | E1 | 4000 | NULL\n\nE4 | 오지민 | 20 | E3 | 3500 | 300\n\nE5 | 서예린 | NULL | E1 | 3000 | 0\n\nE6 | 문태오 | 20 | E3 | 4000 | NULL\n\n[부서] DEPT\n\ndept_id | dept_nm\n\n10 | 개발\n\n20 | 운영\n\n30 | 품질\n\n40 | 기획",
    "options": [
      "NVL(bonus, 0)",
      "CASE bonus WHEN NULL THEN 0 ELSE bonus END",
      "COALESCE(bonus, 0)",
      "CASE WHEN bonus IS NULL THEN 0 ELSE bonus END",
      "NULLIF(bonus, 0)"
    ],
    "answerIndices": [
      0,
      2,
      3
    ],
    "answer": "1. NVL(bonus, 0)\n3. COALESCE(bonus, 0)\n4. CASE WHEN bonus IS NULL THEN 0 ELSE bonus END",
    "explanation": "NVL(Oracle), COALESCE(표준), 검색형 CASE의 IS NULL은 모두 NULL을 0으로 바꿉니다. ②의 단순 CASE는 bonus = NULL로 비교하므로 항상 UNKNOWN이 되어 ELSE로 빠지고 NULL이 그대로 나옵니다. ⑤ NULLIF(bonus, 0)은 bonus가 0이면 NULL을 돌려주는 반대 기능이라 서예린의 0까지 NULL이 됩니다."
